// Economy
TD.ECON = {
  startGold: 60,
  hpScale: 0.55,         // multiplies every enemy's hp (single player tuning)
  goldScale: 2,          // multiplies gold per kill
  waveBonusBase: 15,     // wave 1 pays this
  waveBonusStep: 3,      // each later wave pays this much more
  sellRefund: 0.75,
  coreWave: 25,          // a Core is awarded after wave 25, 50, 75 and so on
  firstWaveDelay: 30,    // seconds before wave 1 (player can start early)
  waveGap: 12,           // seconds between waves (player can start early)
  perfectBonus: 5,       // extra gold for a wave with no lives lost
  buildTime: 3,          // seconds to construct a new tower
  wallTime: 1.2,         // seconds to build a wall
  upgradeTime: 2.5,      // seconds for a tier upgrade
};

TD.DIFFICULTY = {
  easy:    { name: 'Easy',    lives: 50 },
  normal:  { name: 'Normal',  lives: 25 },
  hard:    { name: 'Hard',    lives: 10 },
  perfect: { name: 'Perfect', lives: 1 },
};

// Warcraft III style armour formula.
// 10 armour cuts damage by about 37%. 50 armour cuts it by 75%.
TD.armourFactor = function (armour) {
  const a = 0.06 * armour;
  return 1 - a / (1 + a);
};

// Endless waves -------------------------------------------------------------
//
// From wave 36 the game makes waves from a formula. Enemy strength and player
// income both grow, so a good maze keeps up. A safety check (see below) keeps
// every wave winnable on paper.

TD.ENDLESS = {
  hpGrowth: 1.07,        // hp multiplies by this every wave
  armourEvery: 3,        // +1 armour every N waves
  speedCap: 3.8,         // cells per second, never higher
  countMin: 12,
  countMax: 18,
  goldEvery: 4,          // +1 gold per kill every N waves
  bossEvery: 10,         // every Nth wave is a boss
  bossHpMult: 8,
  flyEvery: 5,
  // Winnability: the "difficulty per gold" of a generated wave may not go
  // above the hardest of the hand made waves 26 to 34, times this allowance.
  // 1.0 keeps late waves exactly as demanding per gold as the map's late
  // waves. Raise it to make endless mode harder.
  allowance: 1.0,
};

const ENDLESS_NAMES = {
  ground: ['Iron Legion', 'Vanguard Column', 'Storm Brigade', 'Bulwark Squad', 'Crusher Tank', 'Phalanx Guard',
           'Ravager Corps', 'Juggernaut', 'Ironclad Convoy', 'Warhound Pack', 'Behemoth', 'Sentinel Line'],
  air:    ['Valkyrie Wing', 'Tempest Squadron', 'Sky Fortress', 'Hornet Flight', 'Raptor Wing', 'Cloud Armada'],
  boss:   ['Colossus', 'Leviathan', 'Goliath', 'Warlord Engine', 'Iron Emperor', 'World Breaker'],
};

// Estimate the gold a player could have collected by the start of wave w.
TD.expectedGoldByWave = function (w) {
  let gold = TD.ECON.startGold;
  for (let i = 1; i < w; i++) {
    const def = TD.getWave(i, true);
    gold += def.count * def.gold;
    gold += TD.ECON.waveBonusBase + TD.ECON.waveBonusStep * (i - 1);
  }
  return gold;
};

// Apply the single player tuning knobs.
TD.scaleWave = function (d) {
  d.hp = Math.max(1, Math.round(d.hp * TD.ECON.hpScale));
  d.gold = Math.max(1, Math.round(d.gold * TD.ECON.goldScale));
  return d;
};

// Decide what the wave looks like and plays like from its number.
// Every 5th wave is a boss. Waves ending in 3 or 8 are air. The rest cycle
// through infantry, buggies and tanks. This replaces the flying/boss flags
// in the hand made table so the rhythm is the same all the way up.
TD.applyKind = function (w, d) {
  const m = w % 5;
  d.flying = false; d.boss = false;
  if (m === 0) {
    d.kind = 'boss'; d.boss = true;
    d.hp = Math.round(d.hp * d.count * 0.7);
    d.gold = Math.round(d.gold * d.count * 1.5);
    d.armour = d.armour + 3;
    d.speed = Math.min(d.speed, 1.1);
    d.count = 1;
    d.name = TD.BOSS_NAMES[(w / 5 - 1) % TD.BOSS_NAMES.length];
  } else {
    if (m === 3) { d.kind = 'heli'; d.flying = true; d.speed = Math.min(d.speed * 0.75, 2.2); }
    else if (m === 1) d.kind = 'inf';
    else if (m === 2) d.kind = 'buggy';
    else d.kind = 'tank';
    const list = TD.KIND_NAMES[d.kind];
    d.name = list[Math.floor((w - 1) / 5) % list.length];
  }
  return d;
};

TD.KIND_NAMES = {
  inf:   ['Rifle Squad', 'Shock Troopers', 'Veteran Squad', 'Elite Guard', 'Storm Brigade', 'Iron Legion', 'Phalanx Guard', 'Vanguard Column'],
  buggy: ['Scout Buggies', 'Half-tracks', 'Attack Bikes', 'Rocket Sleds', 'Raider Column', 'Warhound Pack', 'Ravager Corps'],
  tank:  ['Light Tanks', 'Battle Tanks', 'Siege Tanks', 'Heavy Tanks', 'Titan Tanks', 'Crusher Tanks', 'Behemoths', 'Ironclads'],
  heli:  ['Recon Drones', 'Transport Helis', 'Gunships', 'Stealth Bombers', 'Command Helis', 'Valkyrie Wing', 'Sky Fortress', 'Raptor Wing'],
};

TD.BOSS_NAMES = ['Warlord', 'Iron Colonel', 'The Butcher', 'General Winter', 'Juggernaut', 'Overlord', 'Titan', 'The Marshal', 'Doomhammer', 'Emperor'];

// Hardest "effective hp per expected gold" among the hand made waves 26 to 34.
TD.hardestBaseRatio = function () {
  if (TD._hardest) return TD._hardest;
  let best = 0;
  for (let w = 26; w <= 34; w++) {
    if (w % 5 === 0) continue;
    const d = TD.getWave(w, true);
    const eff = d.hp * d.count / TD.armourFactor(d.armour);
    best = Math.max(best, eff / TD.expectedGoldByWave(w));
  }
  TD._hardest = best;
  return best;
};

// Build a wave definition for wave number w (1 based).
// skipCheck is used internally to avoid recursion in the winnability check.
TD._waveCache = {};
TD.getWave = function (w, skipCheck) {
  if (w <= TD.BASE_WAVES.length) {
    return TD.applyKind(w, TD.scaleWave(Object.assign({}, TD.BASE_WAVES[w - 1])));
  }
  if (!skipCheck && TD._waveCache[w]) return Object.assign({}, TD._waveCache[w]);
  const e = TD.ENDLESS;
  const n = w - TD.BASE_WAVES.length;           // 1, 2, 3 ... into endless
  const ref = TD.BASE_WAVES[TD.BASE_WAVES.length - 2]; // wave 34 as reference
  const boss = false, flying = false;
  let hp = Math.round(ref.hp * Math.pow(e.hpGrowth, n));
  let armour = ref.armour + Math.floor(n / e.armourEvery);
  let speed = Math.min(e.speedCap, ref.speed + n * 0.02);
  let count = e.countMin + ((n * 5) % (e.countMax - e.countMin + 1));
  let gold = ref.gold + Math.floor(n / e.goldEvery);
  let name = ENDLESS_NAMES.ground[n % ENDLESS_NAMES.ground.length];
  if (w % 5 === 3) name = ENDLESS_NAMES.air[n % ENDLESS_NAMES.air.length];

  // Winnability check: scale hp down if the wave would be harder per gold
  // than the hardest hand made wave.
  if (!skipCheck) {
    const ratio = TD.hardestBaseRatio() * e.allowance;
    const budget = TD.expectedGoldByWave(w) * ratio;
    const effectiveHp = hp * TD.ECON.hpScale * count / TD.armourFactor(armour);
    if (effectiveHp > budget) {
      hp = Math.max(100, Math.floor(hp * budget / effectiveHp));
    }
  }
  const out = TD.applyKind(w, TD.scaleWave({ name, hp, armour, speed, count, flying, gold, boss, generated: true }));
  if (!skipCheck) TD._waveCache[w] = out;
  return Object.assign({}, out);
};
